parameters.functionScript:
if (Inputs.question === undefined || Inputs.apiKey === undefined || Inputs.clients === undefined || Inputs.projects === undefined || Inputs.members === undefined || Inputs.wiki === undefined) return;

const clients = Inputs.clients || [];
const projects = Inputs.projects || [];
const members = Inputs.members || [];
const pages = Inputs.wiki || [];
const history = Array.isArray(Inputs.history) ? Inputs.history : [];

const ptrId = function (value) {
  if (typeof value === 'string') return value;
  if (value && value.id) return value.id;
  if (value && value.objectId) return value.objectId;
  return '';
};

const findById = function (list, id) {
  return list.find(function (item) { return item.id === id; });
};

const clientLines = clients.map(function (c) {
  return '- ' + c.name + ' (sector: ' + (c.sector || 'unknown') + ', contact: ' + (c.contactName || 'none') + ', email: ' + (c.email || 'none') + ')';
}).join('\n');

const projectLines = projects.map(function (p) {
  const client = findById(clients, ptrId(p.client));
  const owner = findById(members, ptrId(p.owner));
  return '- ' + p.name + ' — client: ' + (client ? client.name : 'none') + ', status: ' + (p.status || 'none') + ', owner: ' + (owner ? owner.name : 'nobody') + (p.dueDate ? ', due: ' + p.dueDate : '');
}).join('\n');

const wikiLines = pages.map(function (w) {
  return '## ' + w.title + '\n' + (w.body || '').slice(0, 1200);
}).join('\n\n');

const systemPrompt = 'You are the assistant of Atelier Hub, the internal app of a design agency in Lyon. Answer the team\'s questions about clients, projects and wiki pages using ONLY the data below. Be concise, factual and friendly. If the data does not contain the answer, say so plainly.\n\nCLIENTS:\n' + (clientLines || '(none)') + '\n\nPROJECTS:\n' + (projectLines || '(none)') + '\n\nWIKI PAGES:\n' + (wikiLines || '(none)');

const messages = [{ role: 'system', content: systemPrompt }];
history.forEach(function (m) {
  if (m && m.role && m.content) messages.push({ role: m.role, content: String(m.content).slice(0, 4000) });
});
messages.push({ role: 'user', content: Inputs.question });

if (!Inputs.apiKey) {
  Outputs.errorText = 'The MISTRAL_API_KEY secret is not set on the server yet.';
  Outputs.failed();
  return;
}

const response = await fetch('https://api.mistral.ai/v1/chat/completions', {
  method: 'POST',
  headers: {
    'Authorization': 'Bearer ' + Inputs.apiKey,
    'Content-Type': 'application/json'
  },
  body: JSON.stringify({
    model: 'mistral-large-4',
    messages: messages,
    temperature: 0.2
  })
});

if (!response.ok) {
  const detail = await response.text();
  Outputs.errorText = 'Mistral API error ' + response.status + ': ' + detail.slice(0, 300);
  Outputs.failed();
  return;
}

const data = await response.json();
const answer = data && data.choices && data.choices[0] && data.choices[0].message ? data.choices[0].message.content : '';
if (!answer) {
  Outputs.errorText = 'Mistral returned an empty answer.';
  Outputs.failed();
  return;
}
Outputs.answer = answer;
Outputs.finished();
